select public.prepify_load_bank('Chemistry', 4, $j$[["How is the modern periodic table arranged?",["By increasing atomic mass","By decreasing reactivity","By number of neutrons","By increasing the proton number"],"D",3,0,"bac1879e2769",1],["Which block of the periodic table contains the transition metals?",["s-block","d-block","p-block","f-block"],"B",3,0,"f8c950d0c7aa",1],["An element has the electronic configuration 2,8,1. It belongs to:",["Group 1","Group 18","Group 2","Group 17"],"A",3,0,"a2db521d09ec",1],["Which element belongs to the same group as sodium?",["Magnesium","Aluminium","Potassium","Chlorine"],"C",3,0,"41698b9ade75",1],["What is the common name for the elements in Group 17?",["Alkali metals","Noble gases","Alkaline earth metals","Halogens"],"D",3,0,"abd0ba8f1637",1],["As you move from left to right across a period, the atomic radius generally:",["Increases","Decreases","Remains constant","Doubles"],"B",3,0,"cf44df4a51e4",1],["Why do transition metals exhibit variable oxidation states?",["They have large atomic radii.","They have very few electrons.","Their s and d subshell electrons are close enough in energy to be used in bonding.","They are all magnetic."],"C",3,0,"03d024a93ad9",1],["Which group of elements is known for having a full outermost electron shell, making them inert?",["Alkali metals","Halogens","Noble gases","Transition metals"],"C",3,0,"f9262c9c6c99",1],["The \"shielding effect\" is most responsible for:",["Preventing neutron decay","Making the nucleus larger","Increasing electronegativity","The ease of losing electrons in lower group elements"],"D",3,0,"a95bf6a1f338",1],["The trend for atomic radius down a group is an increase because:",["Proton number decreases","New electron shells are added","Electrons are lost","Electronegativity increases"],"B",3,0,"c7a503a1bbe8",1],["Which element has the largest atomic radius?",["Li","Na","K","Rb"],"D",3,0,"69c70846de4a",1],["Lanthanides and actinides belong to:",["s-block","p-block","d-block","f-block"],"D",3,0,"81425c7df873",1],["What defines the \"period\" number of an element?",["The number of valence electrons","The number of electron shells","The number of neutrons","The atomic mass"],"B",3,0,"26ad303ad865",1],["Which element has the highest electronegativity?",["Oxygen","Nitrogen","Fluorine","Chlorine"],"C",3,0,"fbdb8721f81e",1],["Which element is expected to have the highest ionization energy?",["Li","Be","B","Ne"],"D",3,0,"46a99e325551",1],["Which of these is a property of transition metals?",["They are all gases at room temperature","They form colored compounds","They are highly electronegative","They have very low melting points"],"B",3,0,"d6708ae94d82",1],["What does the group number indicate about the valence shell?",["The number of inner shell electrons","The number of protons","The number of valence electrons","The number of neutrons"],"C",3,0,"b9cc050f7348",1],["Two elements are in the same group of the periodic table. Which property is most likely to be similar?",["Number of valence electrons","Atomic mass","Number of shells","Atomic size"],"A",3,0,"b9e1e745fb9f",1],["An element belongs to Period 3 and Group 16. How many occupied shells and valence electrons does it have?",["16 shells, 3 valence electrons","3 shells, 6 valence electrons","3 shells, 16 valence electrons","6 shells, 3 valence electrons"],"B",3,0,"65a1b926a53f",1],["An element lies immediately to the right of sodium in the same period. Compared with sodium, it is expected to have:",["Fewer protons","More occupied shells","Higher ionization energy","Larger atomic radius"],"C",3,0,"8820f10910fa",1],["A student compares fluorine and chlorine. Which property increases from fluorine to chlorine?",["Electron-attracting power","Electronegativity","Ionization energy","Atomic radius"],"D",3,1,"e67ef8e0b950",1],["Which pair of elements is expected to show the greatest similarity in chemical behavior?",["Li and Na","Mg and Al","Na and Mg","Cl and Ar"],"A",3,0,"7caf42d4d282",1],["An element has the electronic configuration 2,8,8. What can be inferred about its chemical activity?",["Highly reactive","Very unreactive","Moderately reactive","Reacts violently with water"],"B",3,0,"baad6d45cd9c",1],["An element in Group 2 forms ions by:",["Gaining two electrons","Sharing eight electrons","Gaining one electron","Losing two electrons"],"D",3,0,"c3b3456a799e",1],["The tendency of an atom to attract electrons in a bond is known to be highest for elements located:",["Lower left of the periodic table","Upper right of the periodic table","Middle of the periodic table only","In Group 1"],"B",3,0,"7ae3b1332e23",1],["Which statement correctly compares sodium and chlorine?",["Both readily lose electrons","Both belong to the same group","Both have identical chemical properties","Sodium tends to lose electrons, while chlorine tends to gain electrons"],"D",3,0,"232287e8b345",1],["An element lies at the extreme right of a period. Which property is most likely?",["Strong metallic character","Tendency to lose electrons easily","High stability due to a complete outer shell","Lowest ionization energy"],"C",3,0,"ab767ec9ead0",1],["Why does the first ionization energy not strictly increase across Period 3, showing a slight dip between Magnesium and Aluminum?",["Aluminum has a larger atomic radius than Magnesium.","Aluminum's valence electron is in a p-subshell, which is slightly further from the nucleus and shielded by the s-subshell.","Magnesium has a higher nuclear charge than Aluminum.","Aluminum has more protons, which repel the valence electrons."],"B",3,0,"b706f3a3732a",0],["Why is the ionic radius of an O²⁻ ion significantly larger than that of a Ne atom, even though they have the same number of electrons?",["Neon is a metal.","The oxygen nucleus is larger.","O²⁻ has fewer protons (8) pulling on the same number of electrons (10), resulting in less effective nuclear attraction.","They have the same nuclear charge."],"C",3,0,"ab46ab31fd30",0],["Consider elements X and Y in the same period. If X is a metal and Y is a non-metal, which is more likely to form an acidic oxide?",["X","Y","Both are equally acidic.","Neither can form oxides."],"B",3,1,"3ace10f1af03",0],["What is the correct order of increasing atomic radius for the isoelectronic series N³⁻, O²⁻, F⁻, Ne, Na⁺?",["N³⁻<O²⁻<F⁻<Ne<Na⁺","Na⁺<Ne<F⁻<O²⁻<N³⁻","Ne<Na⁺<N³⁻<O²⁻<F⁻","N³⁻=O²⁻=F⁻=Ne=Na⁺"],"B",3,0,"b356ec5ca9c3",0],["Why is the ionic radius of a cation smaller than that of its neutral atom?",["Cations lose an electron shell, and remaining electrons experience a higher effective nuclear charge.","Cations gain more protons.","Electrons are heavier than protons.","The nucleus disappears."],"A",3,0,"9038dd4f0800",0],["Which block of the periodic table represents elements whose valence electrons are filling orbitals that are NOT the outermost shell?",["s-block","p-block","d-block","All of the above."],"C",3,0,"e280f444784b",0],["Which factor causes the decrease in electron affinity from Chlorine to Bromine?",["Bromine is a metal.","Loss of s-electrons.","Decreased nuclear charge.","Increased electron-electron repulsion in the larger 4p orbital."],"D",3,0,"cb38cbe4642a",1],["Why are noble gases not truly \"inert\"?",["Because they have no electrons.","Because larger ones (like Xenon) can be forced to react with highly electronegative elements like Fluorine.","Because they are all radioactive.","Because they are actually metals."],"B",3,0,"221aeafb7b91",1],["Why does the atomic radius of transition metals show a \"dip\" in the middle of the period?",["Because protons are lost.","Because they become noble gases.","Because of the change in metallic bonding character as d-orbitals become half-filled.","Because they change into liquids."],"C",3,0,"25b9bd706d74",0],["An element belongs to Group 17. Which statement CANNOT be true?",["It contains seven valence electrons.","It forms a negative ion.","It is chemically inert.","It has a strong tendency to gain electrons."],"C",3,0,"6c96674e46cc",1],["The trend in boiling points for Group 17 (Halogens) is:",["Increasing down the group due to increased Van der Waals forces.","Decreasing down the group.","Constant.","Random."],"A",3,0,"77752c255a92",1],["What does a negative value for electron affinity mean?",["The process is endothermic.","The process is exothermic.","The atom is a metal.","The atom is unstable."],"B",3,0,"2a94af3273dc",0],["Which property measures the \"energy cost\" of adding an electron?",["Electronegativity","Ionization energy","Atomic radius","Electron affinity"],"D",3,1,"4e1ca2c96117",0],["What is the relationship between atomic number and periodicity?",["Periodicity is a function of the repetition of electronic configuration.","It is completely random.","It depends only on mass.","Protons define the color of the element."],"A",3,0,"69bcda99e9ae",0],["What differentiates the actinides from the lanthanides?",["Actinides are all non-metals.","Lanthanides are larger.","Actinides have no electrons.","Lanthanides fill the 4f subshell, while actinides fill the 5f."],"D",3,0,"e740df08420c",1],["Which of these sets represents an isoelectronic series where size is purely determined by proton count?",["F⁻,Na⁺,Mg²⁺","Li,Be,B","Cl,Ar,K","O²⁻,S²⁻,Se²⁻"],"A",3,0,"72f819b94ee5",0],["In the Periodic Table, why is Helium often grouped with s-block elements in some theoretical models?",["It is very dense.","It is a metal.","Its electronic configuration (1s²) matches the s-block filling pattern.","It reacts with oxygen."],"C",3,0,"315f75660d05",0],["The \"Diagonal Relationship\" between Lithium and Magnesium implies they share similar:",["Atomic mass.","Melting points.","Charge density and polarization power.","Number of shells."],"C",3,0,"78c19a06e3cc",1],["Why is atomic radius a \"trend\" rather than an absolute property for all elements in a period?",["Because the periodic table is a diagram.","Because neutrons change the size.","Because atoms are always moving.","Because of varying metallic bonding strengths and orbital occupancy."],"D",3,0,"e99a8dd2e404",0],["What is the most significant factor in the reactivity of Alkali metals?",["High density.","High electronegativity.","Low first ionization energy.","Full valence shells."],"C",3,0,"673b6844a9a4",0],["What does a high electronegativity value indicate about an atom's behavior in a bond?",["It has a strong tendency to attract shared electrons towards itself.","It donates electrons.","It is a poor electron attractor.","It becomes radioactive."],"A",3,0,"3ca557260f50",1],["Why does Carbon show unique bonding compared to other Group 14 elements?",["It is a metal.","It has a small atomic radius, allowing it to form strong multiple bonds (pi-bonds).","It is a noble gas.","It has no protons."],"B",3,0,"01494f8fbb4c",1],["Which period contains the greatest number of elements?",["Period 1","Period 7","Period 3","Period 2"],"B",3,0,"ecbd4e3a207d",1],["What trend is observed in the boiling points of Alkali metals down the group?",["They increase.","They stay constant.","They decrease as the metallic bonding becomes weaker due to larger atomic size.","They are random."],"C",3,1,"9c656422ac64",1],["Which is the most reactive metal in the periodic table?",["Li","Na","Mg","Cs"],"D",3,0,"2cac0c7c76b9",1],["Moving across a period, metallic character decreases mainly because atoms:",["Hold valence electrons more strongly","Lose protons","Become larger","Gain shells"],"A",3,0,"d29bc2c1c852",0],["An element has the electronic configuration 2, 8. It is expected to be:",["highly reactive","very unreactive","a soft metal","a strong reducing agent"],"B",3,0,"baad6d45cd9c",0],["Which element belongs to the same group as chlorine?",["Sulphur","Argon","Bromine","Sodium"],"C",3,0,"41698b9ade75",0],["Which element belongs to the same group as magnesium?",["Sodium","Calcium","Aluminium","Silicon"],"B",3,0,"41698b9ade75",0],["Copper sulphate is blue and iron(III) chloride is yellow-brown. Coloured compounds like these are typical of:",["alkali metals","noble gases","transition metals","halogens"],"C",3,0,"d6708ae94d82",0],["Alkali metals react vigorously with water mainly because they:",["have high density","lose their single valence electron easily","have full valence shells","are non-metals"],"B",3,0,"673b6844a9a4",0],["Going down Group 1 from lithium to potassium, reactivity:",["decreases","increases","stays the same","becomes zero"],"B",3,0,"2cac0c7c76b9",0],["From left to right across a period, metallic character:",["increases","decreases","stays the same","first rises then falls sharply"],"B",3,0,"d29bc2c1c852",0],["Which period has only two elements?",["Period 1","Period 2","Period 3","Period 7"],"A",5,0,"ecbd4e3a207d",0],["An element has the electronic configuration 2, 3. Its position in the periodic table is:",["Period 3, Group 2","Period 3, Group 13","Period 2, Group 14","Period 2, Group 13"],"D",3,0,"gen-chemistry-c4-period-group",0],["An element has the electronic configuration 2, 1. Its position in the periodic table is:",["Period 2, Group 2","Period 2, Group 1","Period 1, Group 2","Period 3, Group 1"],"B",3,0,"gen-chemistry-c4-period-group",0],["An element has the electronic configuration 2, 5. Its position in the periodic table is:",["Period 2, Group 16","Period 3, Group 15","Period 2, Group 15","Period 5, Group 2"],"C",3,0,"gen-chemistry-c4-period-group",0],["An element has the electronic configuration 2, 7. Its position in the periodic table is:",["Period 3, Group 17","Period 2, Group 17","Period 2, Group 18","Period 7, Group 2"],"B",3,0,"gen-chemistry-c4-period-group",0],["An element has the electronic configuration 2, 8, 8, 1. Its position in the periodic table is:",["Period 4, Group 2","Period 4, Group 1","Period 1, Group 4","Period 5, Group 1"],"B",3,0,"gen-chemistry-c4-period-group",0],["An element has the electronic configuration 2, 8, 4. Its position in the periodic table is:",["Period 4, Group 14","Period 4, Group 3","Period 3, Group 14","Period 3, Group 15"],"C",3,0,"gen-chemistry-c4-period-group",0],["Three elements X, Y, and Z have the following valence electrons:\nX = 1\nY = 7\nZ = 8\nWhich pair is most likely to form an ionic compound?",["X and Z","Y and Z","X and Y","X and X"],"C",3,0,"736160a71114",1],["An unknown element is found to:\nGain one electron during reactions.\nHave a smaller atomic radius than sulfur.\nBe in the same period as sulfur.\nThe element is most likely:",["Magnesium","Aluminium","Chlorine","Sodium"],"C",3,0,"7af6b36f750a",1],["A student arranges four elements in order of increasing atomic radius:\nF < O < N < C\nWhich periodic trend is being applied?",["Radius decreases down a group.","Radius decreases from left to right across a period.","Radius increases across a period.","Radius remains constant in a period."],"B",3,0,"d2142a39cf20",1],["Moving across a period, metallic character decreases mainly because atoms:",["Hold valence electrons more strongly","Become larger","Lose protons","Gain shells"],"A",3,0,"d29bc2c1c852",1],["Four elements X, Y, Z, and W belong to the same period.\nX has the largest atomic radius.\nW has the highest ionization energy.\nWhich statement must be true?",["X and W have the same number of valence electrons.","X and W belong to the same group.","X is located to the left of W.","W is located to the left of X."],"C",3,0,"ab8800563760",1],["What is metallic character?",["Ability to gain electrons","Nuclear charge strength","Ability to share electrons","Tendency to lose electrons and form cations"],"D",3,0,"c6682f183070",1],["How does metallic character change down a group?",["Increases","Remains constant","Becomes zero","Decreases"],"A",3,0,"331f3f999e1b",1],["What happens to metallic character across a period from left to right?",["Fluctuates randomly","Remains constant","Decreases","Increases"],"C",3,0,"e0ba6d550738",1],["Which of the following is a characteristic property of alkali metals?",["Soft with low density","Form -1 ions","High melting points","Hard and brittle"],"A",3,0,"2890bfb6b7a6",1],["Why do transition elements form colored compounds?",["d-orbital electron transitions","They have low melting points","They have high density","They are metals"],"A",3,0,"d79b3f6bb2f0",1],["What is electronegativity?",["Energy to remove electrons","Charge on an ion","Number of valence electrons","Ability to attract electrons in a bond"],"D",3,0,"6f576eb7d29a",1],["How does electronegativity change as you move down a group?",["First increases then decrease","Decreases","Remains constant","Increases"],"B",3,0,"e4b81d4ba6d8",1],["What is electron affinity?",["Energy released when electron is added","Energy to remove an electron","Size of electron cloud","Attraction between protons"],"A",3,0,"6eab4bcfd4e1",1],["How does electron affinity generally change across a period?",["Decreases","Remains constant","Increases","Becomes negative"],"C",3,0,"fd4e154956dc",1],["What happens to ionization energy across a period from left to right?",["Decreases","Remains constant","Becomes zero","Increases"],"D",3,0,"f4c38d5cdaaa",1],["How does ionization energy change down a group?",["Remains constant","Decreases","Increases","First decreases then increases"],"B",3,0,"9563ca04ff7a",1],["What is ionization energy?",["Energy required to remove outermost electron","Energy of chemical bonds","Energy to add a proton","Energy released when electron added"],"A",3,0,"4801846e07ab",1],["What charge do Group 17 elements typically form?",["+2","+1","-1","-2"],"C",3,0,"41a2d9fa110c",1],["All the elements of Group IIA are less reactive than alkali metals. This is because these elements have:",["Relatively greater atomic sizes","Similar electronic configuration","High ionization energies","Decreased nuclear charge"],"C",3,0,"4cf32ce33021",1],["Valence shell electronic configuration of an element M (atomic no. 14) is:",["2s²,2p⁶","2s²,2p³","3s²,3p²","2s²,2p¹"],"C",3,0,"f40cd5c38881",1],["Period number of ²⁷₁₃Al is:",["2","3","1","4"],"B",3,0,"5f0cd76f54e2",1],["Rabia's teacher draws part of the periodic table on the board. It shows Periods 2 and 3, and Groups 1, 2 and 13 to 18. She writes letters in some boxes instead of real symbols. A is in Period 2, Group 1. D is in Period 2, Group 17. E is in Period 3, Group 1. G is in Period 3, Group 2. J is in Period 3, Group 16. L is in Period 3, Group 18.\n\nElement G loses electrons to form an ion. What is the charge on this ion?",["+1","+3","+2","-2"],"C",5,1,"66503e0309bd",1],["Rabia's teacher draws part of the periodic table on the board. It shows Periods 2 and 3, and Groups 1, 2 and 13 to 18. She writes letters in some boxes instead of real symbols. A is in Period 2, Group 1. D is in Period 2, Group 17. E is in Period 3, Group 1. G is in Period 3, Group 2. J is in Period 3, Group 16. L is in Period 3, Group 18.\n\nWhich atom is larger, A or E?",["A, because it has fewer electrons","They are the same size, because they are in the same group","A, because it is higher up in the table","E, because it has one more electron shell"],"D",5,1,"8829422d0424",1],["Rabia's teacher draws part of the periodic table on the board. It shows Periods 2 and 3, and Groups 1, 2 and 13 to 18. She writes letters in some boxes instead of real symbols. A is in Period 2, Group 1. D is in Period 2, Group 17. E is in Period 3, Group 1. G is in Period 3, Group 2. J is in Period 3, Group 16. L is in Period 3, Group 18.\n\nWhich of E, G and J has the highest ionization energy?",["J","E","G","All three are same"],"A",5,1,"bec5642e6acb",1],["Rabia's teacher draws part of the periodic table on the board. It shows Periods 2 and 3, and Groups 1, 2 and 13 to 18. She writes letters in some boxes instead of real symbols. A is in Period 2, Group 1. D is in Period 2, Group 17. E is in Period 3, Group 1. G is in Period 3, Group 2. J is in Period 3, Group 16. L is in Period 3, Group 18.\n\nRabia gets a new element with the configuration 1s² 2s² 2p⁶ 3s² 3p⁵. Where does its box go?",["Period 2, Group 17, in the same box as D","Period 3, Group 15, one box left of J","Period 3, Group 17, just below D","Period 5, Group 17"],"C",5,1,"98e915100663",1],["Usman tests three halogens in the school lab. He has three salt solutions: potassium chloride (KCl), potassium bromide (KBr) and potassium iodide (KI). He adds chlorine, bromine or iodine solution to them. He notes whether a new halogen is formed. A dash means he did not test that pair. Chlorine: KCl dash, KBr yes, KI yes. Bromine: KCl no, KBr dash, KI yes. Iodine: KCl no, KBr no, KI dash.\n\nIn how many of Usman's test tubes was a new halogen formed?",["1","2","3","4"],"C",5,1,"4e1b8ca43c31",1],["Usman tests three halogens in the school lab. He has three salt solutions: potassium chloride (KCl), potassium bromide (KBr) and potassium iodide (KI). He adds chlorine, bromine or iodine solution to them. He notes whether a new halogen is formed. A dash means he did not test that pair. Chlorine: KCl dash, KBr yes, KI yes. Bromine: KCl no, KBr dash, KI yes. Iodine: KCl no, KBr no, KI dash.\n\nWhich halogen displaced (took the place of) both of the other halide ions?",["Iodine","Bromine","Chlorine","None of them"],"C",5,1,"1bbb12efb5b6",1],["Usman tests three halogens in the school lab. He has three salt solutions: potassium chloride (KCl), potassium bromide (KBr) and potassium iodide (KI). He adds chlorine, bromine or iodine solution to them. He notes whether a new halogen is formed. A dash means he did not test that pair. Chlorine: KCl dash, KBr yes, KI yes. Bromine: KCl no, KBr dash, KI yes. Iodine: KCl no, KBr no, KI dash.\n\nWhich equation shows what happened in the tube with bromine and KI?",["Br₂+2KI→2KBr+I₂","Br₂+KI→KBr+I₂","I₂+2KBr→2KI+Br₂","Br₂+2KI→2KBrI"],"A",5,1,"ad79811b0cf6",1],["Usman tests three halogens in the school lab. He has three salt solutions: potassium chloride (KCl), potassium bromide (KBr) and potassium iodide (KI). He adds chlorine, bromine or iodine solution to them. He notes whether a new halogen is formed. A dash means he did not test that pair. Chlorine: KCl dash, KBr yes, KI yes. Bromine: KCl no, KBr dash, KI yes. Iodine: KCl no, KBr no, KI dash.\n\nUsman did not test fluorine. What will happen if fluorine is added to KCl solution?",["Nothing, because fluorine is the lightest halogen","Chlorine will form, because fluorine is above chlorine in Group 17","Iodine will form","Nothing, because chloride ions can never be displaced"],"B",5,1,"cb6de3723f2a",1],["Three elements X, Y and Z are in the same period. Their valence-shell electronic configurations are X: 3s² 3p¹, Y: 3s² 3p⁴ and Z: 3s² 3p⁶. A student observes that atomic size decreases from X to Z, while ionization energy and electronegativity generally increase.\n\nWhich element has the smallest atomic radius?",["X","Y","Z","All have the same radius"],"C",5,1,"938989a434e1",1],["Three elements X, Y and Z are in the same period. Their valence-shell electronic configurations are X: 3s² 3p¹, Y: 3s² 3p⁴ and Z: 3s² 3p⁶. A student observes that atomic size decreases from X to Z, while ionization energy and electronegativity generally increase.\n\nWhich element has the greatest tendency to attract shared electrons in a covalent bond?",["X","Y","Z","X and Z equally"],"B",5,1,"d109f464844c",1],["Three elements X, Y and Z are in the same period. Their valence-shell electronic configurations are X: 3s² 3p¹, Y: 3s² 3p⁴ and Z: 3s² 3p⁶. A student observes that atomic size decreases from X to Z, while ionization energy and electronegativity generally increase.\n\nWhich statement best explains the decrease in atomic size from X to Z?",["Number of electron shells increases","Nuclear charge increases while the electrons remain in the same principal shell","Shielding effect increases greatly","Number of neutrons decreases"],"B",5,1,"ca1875c9906e",1],["Three elements X, Y and Z are in the same period. Their valence-shell electronic configurations are X: 3s² 3p¹, Y: 3s² 3p⁴ and Z: 3s² 3p⁶. A student observes that atomic size decreases from X to Z, while ionization energy and electronegativity generally increase.\n\nIf X loses three electrons, the resulting ion will most likely have the electronic configuration of:",["Y","Z","A lower period noble gas","A transition element"],"C",5,1,"064c24378811",1],["Three elements X, Y and Z are in the same period. Their valence-shell electronic configurations are X: 3s² 3p¹, Y: 3s² 3p⁴ and Z: 3s² 3p⁶. A student observes that atomic size decreases from X to Z, while ionization energy and electronegativity generally increase.\n\nWhich element would require the greatest energy to remove one electron from its outermost shell?",["X","Y","Z","X and Y equally"],"C",5,1,"46532dfe9158",1],["Elements A, B, and C belong to the same group. Their atomic numbers are 3, 11, and 19, respectively. A student compares their properties and finds that the outermost electron of C is farther from the nucleus than that of A.\n\nWhich element will have the greatest shielding effect?",["A","B","C","All have equal shielding effect"],"C",5,1,"d9402c8dee70",1],["Elements A, B, and C belong to the same group. Their atomic numbers are 3, 11, and 19, respectively. A student compares their properties and finds that the outermost electron of C is farther from the nucleus than that of A.\n\nWhich order represents the correct trend of atomic size?",["A > B > C","C > B > A","B > A > C","A = B = C"],"B",5,1,"fb8967fb7fbd",1],["Elements A, B, and C belong to the same group. Their atomic numbers are 3, 11, and 19, respectively. A student compares their properties and finds that the outermost electron of C is farther from the nucleus than that of A.\n\nWhich element is expected to have the highest first ionization energy?",["A","B","C","B and C equally"],"A",5,1,"d2b1178f75a3",1],["Elements A, B, and C belong to the same group. Their atomic numbers are 3, 11, and 19, respectively. A student compares their properties and finds that the outermost electron of C is farther from the nucleus than that of A.\n\nIf A, B, and C react with a halogen, which common ion is most likely formed by each?",["A⁻, B⁻, C⁻","A²⁺, B²⁺, C²⁺","A⁺, B⁺, C⁺","A³⁺, B³⁺, C³⁺"],"C",5,1,"088c57eb2482",1]]$j$::jsonb, true);
